package com.masalewala.api.config;
import com.masalewala.api.model.Models.*;import com.masalewala.api.repository.Repositories.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.crypto.password.PasswordEncoder;import java.math.BigDecimal;import java.util.*;
@Configuration public class DataSeeder{@Bean CommandLineRunner seed(Categories categories,Products products,Users users,PasswordEncoder encoder){return args->{if(users.count()==0){var admin=new User();admin.email="admin@masalewala.in";admin.name="Admin";admin.passwordHash=encoder.encode("Admin@12345");admin.roles.add(RoleName.ADMIN);users.save(admin);}if(categories.count()>0)return;var names=List.of("Turmeric Powder (Haldi)","Red Chilli Powder","Coriander Powder","Cumin Powder","Garam Masala","Kitchen King Masala","Chole Masala","Pav Bhaji Masala","Biryani Masala","Chicken Masala","Meat Masala","Sabzi Masala","Sambar Masala","Rasam Powder","Chaat Masala","Tea Masala","Paneer Masala","Fish Masala","Achar Masala","Shahi Paneer Masala");int i=0;for(String n:names){var c=new Category();c.name=n;c.slug=n.toLowerCase().replaceAll("[^a-z0-9]+","-");c.imageUrl="https://source.unsplash.com/600x500/?indian-spices";categories.save(c);var p=new Product();p.name=n;p.description="Freshly ground premium Indian spice packed for aroma and purity.";p.price=BigDecimal.valueOf(89+(i%5)*30);p.discount=10+i%4*3;p.stock=50+i*8;p.rating=4.5+(i%5)*.1;p.reviews=40+i*11;p.imageUrl=c.imageUrl;p.category=c;p.bestSeller=i%3==0;p.newest=i%4==0;products.save(p);i++;}};}}
